// === Tab: mySketch ===
//Code and pallette by Aaron Reuland
//Abstract art using a video feedback loop 

let colors = ["#a7f7f7", "#82964e", "#567963", "#5981a5", "#264b5d", "#323227"]
let points = []
let dots = []
let liners = []
let colorIndex = 0
let bgFiller, bgPt
function setup() {
	createCanvas(windowWidth, windowHeight);
	let bgColorIndex = floor(random(colors.length))
	let bgColor = colors[0]
	colors.splice(0, 1)
	background(bgColor);
	bgFiller = color(bgColor)
	bgFiller.setAlpha(5)


	for (let i = 0; i < 25; i++) {
		let x = width / 2 + randomGaussian(0, width / 4)
		let y = height / 2 + randomGaussian(0, height / 4)
		let r = random(height / 10, height / 50)
		dots.push(new dot(x, y, r, colorIndex))
		colorIndex++
	}

	for (let i = 0; i < 8; i++) {
		var x = random(width)
		let w = random(width / 50, width / 15)
		liners.push(new liner(x, w, colorIndex))
		colorIndex++
	}
}

function draw() {

	filter(BLUR, 2)
	fill(bgFiller)
	push()
	blendMode(SCREEN)
	rect(0, 0, width, height)
	pop()


	let g = get()
	ranScale = random(-.02, 0.2)
	image(g, 0, 0, width + ranScale, height + ranScale)


	for (let d of dots) {
		d.die()
		d.dye();
	}

	for (let l of liners) {
		l.drawn();
		l.draw();
	}


	if (frameCount % 60 == 0) {
		for (let i = 0; i < 25; i++) {
			var x = width / 2 + randomGaussian(0, width / 4)
			var y = height / 2 + randomGaussian(0, height / 4)
			var r = random(height / 10, height / 50)
			dots.push(new dot(x, y, r, colorIndex))
			colorIndex++
		}
	}

	if (frameCount % 33 == 0) {
		for (let i = 0; i < 8; i++) {
			var x = random(width)
			var w = random(width / 50, width / 15)
			liners.push(new liner(x, w, colorIndex))
			colorIndex++
		}
	}


}



function colorMixer(x, y, colorArray, it) {

	let c = noise(x / 50, y / 50, it / 30) * colorArray.length
	let c1 = floor(c)
	let c2 = floor(c + 1) % colorArray.length
	let color1 = colorArray[c1]
	let color2 = colorArray[c2]
	let mix = fract(c)
	let coloring = color(spectral.mix(color1, color2, mix))
	return coloring
}

class dot {
	constructor(x, y, s, colorSeed) {
		this.x = x
		this.y = y
		this.s = s
		this.c = colorSeed
		this.totalFrames = 60
	}

	die() {
		this.totalFrames--
		if (this.totalFrames <= 0) {
			let index = dots.indexOf(this)
			dots.splice(index, 1)
		}
		this.y++
		this.x += random(-1, 1)
	}

	dye() {
		noStroke()
		var c = colorMixer(this.x, this.y, colors, this.c)
		fill(c)
		//	let s= map(this.totalFrames, 60, 0, this.s, this.s/10)
		ellipse(this.x, this.y, this.s)
	}

}


class liner {
	constructor(x, w, colorIndex) {
		this.x = x;
		this.w = w;
		this.frames = 33
		this.color = colors[colorIndex % colors.length]
	}

	drawn() {
		this.frames--
		if (this.frames <= 0) {
			var index = liners.indexOf(this)
			liners.splice(index, 1)
		}

	}

	draw() {
		noStroke()
		fill(this.color)
		let shift = map(noise(this.x, frameCount / 100), 0, 1, -this.w / 2, this.w / 2)
		beginShape()
		for (let y = -10; y < height + 10; y += 10) {
			let bark = noise(this.x, y) * this.w / 10
			vertex(this.x + bark + shift, y)
		}
		for (let y = height + 10; y > -10; y -= 10) {
			var bark = noise(this.x + this.w, y) * this.w / 10
			vertex(this.x + shift - bark, y)
		}
		endShape(CLOSE)
	}
}

